/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
s=''.join(x.strip() for x in Path('orf.annot.q1.fa').read_text().splitlines() if not x.startswith('>')).upper().replace('T','U')
print('length',len(s))
stops={'UAA','UAG','UGA'}
starts=[]
for i in range(len(s)-2):
    if s[i:i+3]=='AUG':
        # first in-frame stop
        j=i+3
        while j+2<len(s) and s[j:j+3] not in stops:
            j+=3
        if j+2<len(s):
            prot=(j-i)//3
            starts.append((i,j,prot,s[j:j+3]))
        else:
            starts.append((i,None,None,None))
print('AUG count',len(starts))
for x in starts:
 print(x, s[max(0,x[0]-15):x[0]+18])
print('longest complete',max((x for x in starts if x[1] is not None),key=lambda x:x[2]))
PY"
